    Value makeFloatFromLiteral(gocpp::string lit)
    {
        if(auto [f, ok] = rec::SetString(gocpp::recv(newFloat()), lit); ok)
        {
            if(smallFloat(f))
            {
                // ok to use rationals
                if(rec::Sign(gocpp::recv(f)) == 0)
                {
                    // Issue 20228: If the float underflowed to zero, parse just "0".
                    // Otherwise, lit might contain a value with a large negative exponent,
                    // such as -6e-1886451601. As a float, that will underflow to 0,
                    // but it'll take forever to parse as a Rat.
                    lit = "0"_s;
                }
                if(auto [r, ok] = rec::SetString(gocpp::recv(newRat()), lit); ok)
                {
                    return ratVal {r};
                }
            }
            // otherwise use floats
            return makeFloat(f);
        }
        return nullptr;
    }

