    // MakeFromLiteral returns the corresponding integer, floating-point,
    // imaginary, character, or string value for a Go literal string. The
    // tok value must be one of [token.INT], [token.FLOAT], [token.IMAG],
    // [token.CHAR], or [token.STRING]. The final argument must be zero.
    // If the literal string syntax is invalid, the result is an [Unknown].
    Value MakeFromLiteral(gocpp::string lit, token::Token tok, unsigned int zero)
    {
        if(zero != 0)
        {
            gocpp::panic("MakeFromLiteral called with non-zero last argument"_s);
        }

        //Go switch emulation
        {
            auto condition = tok;
            int conditionId = -1;
            if(condition == token::INT) { conditionId = 0; }
            else if(condition == token::FLOAT) { conditionId = 1; }
            else if(condition == token::IMAG) { conditionId = 2; }
            else if(condition == token::CHAR) { conditionId = 3; }
            else if(condition == token::STRING) { conditionId = 4; }
            switch(conditionId)
            {
                case 0:
                    if(auto [x, err] = strconv::ParseInt(lit, 0, 64); err == nullptr)
                    {
                        return int64Val(x);
                    }
                    if(auto [x, ok] = rec::SetString(gocpp::recv(newInt()), lit, 0); ok)
                    {
                        return intVal {x};
                    }
                    break;

                case 1:
                    if(auto x = makeFloatFromLiteral(lit); x != nullptr)
                    {
                        return x;
                    }
                    break;

                case 2:
                    if(auto n = len(lit); n > 0 && lit[n - 1] == 'i')
                    {
                        if(auto im = makeFloatFromLiteral(lit.make_slice(0, n - 1)); im != nullptr)
                        {
                            return makeComplex(int64Val(0), im);
                        }
                    }
                    break;

                case 3:
                    if(auto n = len(lit); n >= 2)
                    {
                        if(auto [code, gocpp_id_4, gocpp_id_5, err] = strconv::UnquoteChar(lit.make_slice(1, n - 1), '\''); err == nullptr)
                        {
                            return MakeInt64(int64_t(code));
                        }
                    }
                    break;

                case 4:
                    if(auto [s, err] = strconv::Unquote(lit); err == nullptr)
                    {
                        return MakeString(s);
                    }
                    break;

                default:
                    gocpp::panic(mocklib::Sprintf("%v is not a valid token"_s, tok));
                    break;
            }
        }

        return unknownVal {};
    }

